const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to evaluate server-side objects
  const evaluate = (obj) =>
    new Promise((resolve, reject) => {
      obj.evaluate((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });

  try {
    // 1. Geometry & Time Definitions
    const lon = -125.410394;
    const lat = -41.729403;
    const region = ee.Geometry.Point([lon, lat]).buffer(100000); // 100 km radius
    const scale = 4000;

    const priorStart = '2018-11-01';
    const priorEndExcl = '2019-03-01';  // exclusive
    const currStart = '2019-11-01';
    const currEndExcl = '2020-03-01';   // exclusive

    const primaryDs = 'NASA/OCEANDATA/MODIS-Aqua/L3SMI';
    const fallbackDs = 'NASA/OCEANDATA/MODIS-Terra/L3SMI';

    // Constant total pixel count at analysis scale
    const totalPix = await evaluate(
      ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('ones')
    );

    // Function to get stats for a period with dataset and fallback/widen
    async function getPeriodStats(start, endExcl) {
      async function tryDataset(dsId, s, e) {
        const col = ee.ImageCollection(dsId)
          .filterDate(s, e)
          .filterBounds(region)
          .select('chlor_a');
        const n = await evaluate(col.size());
        if (n === 0) return {ok: false, reason: `No images in ${dsId}`};

        const composite = col.median();
        const countDict = composite.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        });
        const meanDict = composite.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9
        });

        const validPix = await evaluate(countDict.get('chlor_a'));
        const mean = await evaluate(meanDict.get('chlor_a'));

        return {ok: true, dsId, n, validPix, mean};
      }

      // Try primary
      let res = await tryDataset(primaryDs, start, endExcl);
      if (!res.ok) {
        // Try fallback dataset
        res = await tryDataset(fallbackDs, start, endExcl);
      }
      if (!res.ok) {
        // Widen window by ±15 days on primary
        const sWide = await evaluate(ee.Date(start).advance(-15, 'day').format('YYYY-MM-dd'));
        const eWide = await evaluate(ee.Date(endExcl).advance(15, 'day').format('YYYY-MM-dd'));
        res = await tryDataset(primaryDs, sWide, eWide);
        if (!res.ok) return {status: 'C1', msg: `Empty Collection after recovery: ${res.reason}`};
      }

      // Check valid pixels
      if (!res.validPix || res.validPix === 0) {
        return {status: 'C2', msg: `No valid pixels after masking (dataset: ${res.dsId})`};
      }
      // Check mean validity
      if (res.mean === null || res.mean === undefined || !isFinite(res.mean)) {
        return {status: 'C3', msg: 'Mean is null/NaN/invalid'};
      }
      return {
        status: 'OK',
        dsId: res.dsId,
        n: res.n,
        validPix: res.validPix,
        mean: res.mean
      };
    }

    // 2. Data Acquisition & Checks
    console.log(`Geom: (${lon.toFixed(6)},${lat.toFixed(6)}) r=100km, scale=${scale}m`);
    console.log(`Dataset preference: MODIS Aqua L3SMI (chlor_a)`);

    const prior = await getPeriodStats(priorStart, priorEndExcl);
    if (prior.status !== 'OK') {
      console.log(`Prev (2018-11-01 to 2019-03-01): ${prior.msg}`);
      console.log('C1' === prior.status ? 'C1' : prior.status);
      return;
    }
    const curr = await getPeriodStats(currStart, currEndExcl);
    if (curr.status !== 'OK') {
      console.log(`Curr (2019-11-01 to 2020-03-01): ${curr.msg}`);
      console.log('C1' === curr.status ? 'C1' : curr.status);
      return;
    }

    // 3. Processing & Validation
    const priorValidPct = totalPix > 0 ? (100.0 * prior.validPix / totalPix) : 0;
    const currValidPct = totalPix > 0 ? (100.0 * curr.validPix / totalPix) : 0;

    // 4. Output concise stats
    console.log(`Prev (2018-11-01 to 2019-03-01) Images: ${prior.n}, Valid: ${prior.validPix}/${totalPix} (${priorValidPct.toFixed(1)}%), Mean: ${prior.mean.toFixed(3)} mg m^-3 [${prior.dsId}]`);
    console.log(`Curr (2019-11-01 to 2020-03-01) Images: ${curr.n}, Valid: ${curr.validPix}/${totalPix} (${currValidPct.toFixed(1)}%), Mean: ${curr.mean.toFixed(3)} mg m^-3 [${curr.dsId}]`);

    if (prior.mean === 0 && curr.mean === 0) {
      console.log('C3');
      return;
    }

    const delta = curr.mean - prior.mean;
    const pct = prior.mean !== 0 ? (100 * delta / prior.mean) : null;
    const pctStr = (pct === null || !isFinite(pct)) ? 'n/a' : `${pct.toFixed(1)}%`;
    console.log(`Change: ${delta.toFixed(3)} mg m^-3 (${pctStr})`);

    // 5. Final Answer
    if (!isFinite(prior.mean) || !isFinite(curr.mean)) {
      console.log('C3');
    } else if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
